import{_ as o,o as r,c as u,ag as n}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"05 投资交易知识手册","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/tianya/handbook/05_投资交易知识手册.md","filePath":"topics/tianya/handbook/05_投资交易知识手册.md"}'),q={name:"topics/tianya/handbook/05_投资交易知识手册.md"};function s(g,t,a,d,l,i){return r(),u("div",null,[...t[0]||(t[0]=[n('<h1 id="_05-投资交易知识手册" tabindex="-1">05 投资交易知识手册 <a class="header-anchor" href="#_05-投资交易知识手册" aria-label="Permalink to &quot;05 投资交易知识手册&quot;">​</a></h1><blockquote><p>知识来源：天涯神贴 10 篇实盘/亲历贴（帖号标注：77 南侠1987杠杆投机 / 153 数字哥短线 / 191 岑若曦涨停板 / 64 peterwind期货 / 205 时代之市场心理 / 120 赌场二年 / 22 老千世界 / 208 冻云迷雾虚拟货币 / 139 万里依然销售创业 / 182 目光呆滞的润土企业家自传）。凡推演结论均标【推演】，其余为原帖陈述或原帖数字的整理。</p></blockquote><hr><h2 id="一、仓位与杠杆的数学" tabindex="-1">一、仓位与杠杆的数学 <a class="header-anchor" href="#一、仓位与杠杆的数学" aria-label="Permalink to &quot;一、仓位与杠杆的数学&quot;">​</a></h2><h3 id="_1-1-配资爆仓的完整数字链条-77" tabindex="-1">1.1 配资爆仓的完整数字链条（77） <a class="header-anchor" href="#_1-1-配资爆仓的完整数字链条-77" aria-label="Permalink to &quot;1.1 配资爆仓的完整数字链条（77）&quot;">​</a></h3><p><strong>强平规则</strong>：配资合同规定，自有本金亏损达 70% 且未追加保证金，配资公司即强行平仓全部卖出——这是保护配资公司资金的线，不是保护你的线。</p><p><strong>杠杆与爆仓的换算（77 原文数字）</strong>：6 倍杠杆下，标的只需下跌 <strong>13%</strong>，自有本金即损失 70%，触及强平；下跌 <strong>16%</strong>，本金基本归零。【推演】亏损放大倍数≈杠杆倍数：6 倍杠杆 × 标的跌幅 13% ≈ 本金 -78%。A 股单日跌停 10%，意味着<strong>两个跌停（-19%）足以让 6 倍杠杆者本金归零</strong>——而 77 作者亲历的 2015 年 6—8 月，连续 3 波&quot;千股跌停&quot;真实发生。</p><p><strong>收益侧的同一条数学（77 推演表）</strong>：50 万本金，1:5 配资，每涨约 10% 就把浮盈全部加仓，则 50 万→72 万→124 万→196 万（1:5 配 980 万）→……连涨 9 个 10%，自有资金变为 3430 万；8 个 10%（股价翻倍）≈ 盈利 42 倍。这就是&quot;股价涨一倍、4 倍配资玩到 30 倍利润&quot;的来源。<strong>注意：这条数学的成立条件是&quot;每个 10% 都不加杠杆死扛回调&quot;——它对回撤的容忍度是零</strong>，因为浮盈加仓会把每一次利润都变成新的风险敞口。</p><p><strong>猛人案例（77，2014 年 12 月 9 日）</strong>：3100 万自有 + 1.55 亿配资（合计约 1.86 亿）；当天上午涨 5% 时把浮盈 500 万加仓，随后证券股从涨停到跌停：当天买入的票 T+1 无法卖出，强平保护失效；当日亏损 15% ≈ 2800 万，3100 万两小时只剩 300 万；次日盘中跌至 -9%，配资公司果断强平，<strong>只剩 90 多万</strong>。随后证券股被强力拉升——但&quot;他的筹码已经没有了&quot;。三个教训：① T+1 当天买入=强平保护失效；② 浮盈加仓=在最高点把利润换成仓位；③ 反弹与爆仓者无关。</p><p><strong>南侠本人 119 股灾（2015 年 1 月 19—20 日，77）</strong>：券商板块因两融检查集体跌停，其自有资金 周四 2100 万→周五 1800 万→周一 850 万，补 50 万保证金后仍被强平至 <strong>70 万</strong>。他事后测算：<strong>若预留 300 万机动资金</strong>补保证金，可扛过最低点——2 月底解套、4 月中旬券商再涨，账户本可到 8400 万。<strong>300 万（约本金 15%）的预算外现金，就是千万级账户的生死线。</strong></p><p><strong>第二次爆仓（77）</strong>：70 万配资 350 万利滚利重做到 5000 万；2015 年 6 月 15 日起两波股灾，&quot;哪怕全都四个跌停都扛得住&quot;的自信（参照历史上最惨的 530 也才三个多跌停）被&quot;千股跌停&quot;击穿——<strong>&quot;历史上没发生过&quot;不是风控参数</strong>。</p><p><strong>&quot;永远不重仓&quot;的操作定义（64）</strong>：① 仓位 = 趋势状态（多/空/震荡）× 级别（小/大/最大），震荡状态只许平仓、禁止加仓；② 节假日一律极轻仓（08 年国庆金属单月暴跌 40%，10 倍杠杆账户即 -400%）；③ 浮盈先取走一半落袋（其 2 月账户 3 万→6 万，取走 1.8 万，留 4 万余继续）；④ 大机会单次也只投总资金 10%——&quot;季度抓一次、每次 10%，年化即超 40%&quot;。</p><p><strong>常识版凯利【推演，基于 77/64/153 数字】</strong>：不必精确计算凯利公式，只需满足三条不等式——① 单笔最大亏损 × 预期连续止损次数（按系统历史取 5—10 次）≤ 总资金的 30%；② 杠杆倍数 ≤ 1 ÷（历史最大单日跌幅 × 2），按 A 股千股跌停单日 -8% 计，杠杆上限约 5—6 倍，但连续两日即 -16%，故实盘应再减半；③ 预算外机动现金（补保证金专用）≥ 本金 15%（77 的 300 万/2100 万）。<strong>幸存者的共性不是算得准，而是保证任何一次坏运气都打不出局。</strong></p><hr><h2 id="二、短线系统三套-可执行规则清单" tabindex="-1">二、短线系统三套（可执行规则清单） <a class="header-anchor" href="#二、短线系统三套-可执行规则清单" aria-label="Permalink to &quot;二、短线系统三套（可执行规则清单）&quot;">​</a></h2><h3 id="_2-1-岑若曦-只做最强-涨停股模式-191" tabindex="-1">2.1 岑若曦：只做最强/涨停股模式（191） <a class="header-anchor" href="#_2-1-岑若曦-只做最强-涨停股模式-191" aria-label="Permalink to &quot;2.1 岑若曦：只做最强/涨停股模式（191）&quot;">​</a></h3><p><strong>选股</strong>：</p><ul><li>只做&quot;涨停过的强势股&quot;——涨停是主力做多情绪的最大化体现，研究涨停行为=研究主力心理学；妖股、明星股、热点龙头无一不是从涨停走出来。</li><li>只做当前市场前 3—4 大热点（2015.7：猪肉、央企改革、高送转、军工；2020.2：大科技、新能源），&quot;在一堆能涨的板块里找好股，比在废物堆里找精品容易得多&quot;。</li><li>识别伪热点：板块龙头持续低迷、老二反而活跃（楚天高速案例）→ 定性伪热点，预期降级为&quot;亏 5% 以内出局&quot;。</li></ul><p><strong>入场</strong>：</p><ul><li>只参与拉升段，不参与建仓、洗盘、震仓、出货。</li><li>分时引爆点买入（&quot;一买就涨&quot;的分时读盘能力是短线基本功）；<strong>买点一过坚决不追</strong>——&quot;宁可错过，不能做错&quot;，保住成功率是生命线。</li></ul><p><strong>仓位</strong>：最多 3 只，做精不做多；错过牛股=彩票没中奖，不懊恼。</p><p><strong>止损/止盈</strong>：</p><ul><li>实盘止损样本：三维通信 -3% 止损、园城黄金 -3%、津滨发展 -6%；&quot;止损卖出 10 余分钟后大盘立即跳水 200 点&quot;——止损买的是确定性。</li><li>止盈即交易结束：卖出后该股再涨 10 倍&quot;都与你无关，你只需赚你看得懂的钱&quot;。</li><li>预期管理随行情动态降级：从&quot;赚钱&quot;改为&quot;亏 5% 以内出局&quot;，&quot;市场不会来适应你，只能你去适应市场&quot;。</li></ul><p><strong>纪律</strong>：</p><ul><li>复利公式：&quot;持股 10 天赚 30%，与 10 天做 10 只股每只赚 3% 效果一样，后者利润更大（复利）&quot;。</li><li>极端日认知：2750 只个股 2000 余只跌停当日，&quot;最好的操作是空仓&quot;——作者承认自己没做到（激进打错单），这是该模式的天敌：<strong>系统只覆盖常态行情，覆盖不了系统性崩盘</strong>。</li><li>不预测指数：&quot;我预测指数能力为 0，有的只是盘感&quot;，救大盘的只能是热点，银行石油&quot;只能拿来躲雨，不能拿来赚钱&quot;。</li></ul><h3 id="_2-2-数字哥-缠论-macd-背离高抛低吸-153" tabindex="-1">2.2 数字哥：缠论 + MACD 背离高抛低吸（153） <a class="header-anchor" href="#_2-2-数字哥-缠论-macd-背离高抛低吸-153" aria-label="Permalink to &quot;2.2 数字哥：缠论 + MACD 背离高抛低吸（153）&quot;">​</a></h3><p><strong>技术底座</strong>：缠论 108 节只学前 10 章（精华，后文&quot;看了甚至有反作用&quot;）；MACD 用默认参数，不调参；核心工具=分钟级顶底背离。</p><p><strong>当日基调判定</strong>：开盘 1、3、5 分钟顶背离共振 → 全天主基调做空，目标幅度约 10 个点 → 滚动放空；底背离共振则反向。实盘样本：一天 6 轮高抛低吸共 18 个点，1 手 5400 元，10 手单日 5.4 万（期指 IF）。</p><p><strong>建仓（股票）</strong>：</p><ul><li>底部区域&quot;从高往低买，主动带套&quot;，分批吸纳 + 短线资金高抛低吸摊低成本（&quot;建仓，建仓，建仓&quot;）；</li><li>强势创新高股用缠论第三类买点；完全控盘的连板妖股不参与；</li><li>KDJ 超买处理：强势股单日即可修复（低开或冲高回落），弱势股需数日下跌修复——&quot;单独 K 线意义不大，要跟踪盘面理解主力想法&quot;。</li></ul><p><strong>持仓</strong>：&quot;中线选股，短线操作，滚动利润&quot;，但必须全程盯盘（震荡交易系统是辛苦的体力活）；做 T 底仓不动，走弱踢出底仓维持仓位不变。</p><p><strong>边界（作者原话）</strong>：技术是&quot;稳定持续盈利的方法，不是应对极端情况的方法&quot;——一纸公告停牌一年、无征兆连跌 10 停板，&quot;只能自求多福&quot;，运气也是炒股票的一部分。选股时即剔除过去涨 10 倍的超级妖股以回避此风险。</p><p><strong>心法</strong>：买股票的理由不是&quot;这股票很好&quot;，而是&quot;这股票该买&quot;（好股票大盘跌了一样跌）；最烂的股票跌到 1 元也去抢——<strong>买入决策=价格与位置的函数，不是公司好坏的函数</strong>。</p><h3 id="_2-3-peterwind-大突破策略与多周期共振-64" tabindex="-1">2.3 peterwind：大突破策略与多周期共振（64） <a class="header-anchor" href="#_2-3-peterwind-大突破策略与多周期共振-64" aria-label="Permalink to &quot;2.3 peterwind：大突破策略与多周期共振（64）&quot;">​</a></h3><p><strong>定义</strong>：用模糊集合算法定义&quot;大&quot;（共振度高者=大），只做时间、空间都明确的大趋势突破；点位由系统提前算出，但<strong>开单依据是&quot;走势符合模型&quot;而非点位本身</strong>。</p><p><strong>开仓条件（全部满足才开单）</strong>：① 斜率有攻击角度；② 跳空突破关键位置；③ 第二/三次突破前期大旗杆、前高前低、昨前日高低点；④ 平盘时间够长、空间够大；⑤ 趋势通道状态发生突破改变，关键点共振度&gt;3（轨道上下轨与前期大趋势点共振度高于 3 时仓位加 1 档）；⑥ 通道状态与当前状态一致（当前低多则通道必须低多，且均线 5 分之 4 呈低多倾斜；震荡禁止加仓）；⑦ 量能温和或放量、无背离、有大资金关注；⑧ MACD、KDJ、BOLL 三指标同时支持同一方向。</p><p><strong>仓位</strong>：状态（多/空/震荡）×级别（小/大/最大）二维定仓；期货永远轻仓；节假日极轻仓；浮盈取半。</p><p><strong>止盈止损（三套并用）</strong>：</p><ul><li>时间维度（斐波那契）：做多后第 5、8、13 个交易日分别平仓 30%、40%、30%；</li><li>空间维度（马尔科夫式关键位）：到目标位全清仓（玻璃 1601 目标 958），破关键位全止损（850），回踩 876 不破=二次确认；</li><li>状态维度：趋势转震荡，至少平出一半，甚至转短空——&quot;资金永远与趋势状态相匹配&quot;。</li></ul><p><strong>频率与预期</strong>：日线级别一年机会 ≥100 次，周月线只有几次；只做大的，一年几次足矣。样本：白银大突破策略一周 +100%——<strong>大机会出现后休息三个月也值得</strong>。</p><p><strong>哲学内核</strong>：交易之道只有一个字&quot;空&quot;=放空自己、追随趋势；&quot;重要的是追随趋势交易，而不是预测趋势&quot;；开平仓与上一单的盈亏无关，只与当前趋势状态有关。顶底识别经验：&quot;没有疯狂的来回震荡，这里就不会是顶底。&quot;</p><hr><h2 id="三、交易心理-贪嗔痴慢疑的完整映射-205" tabindex="-1">三、交易心理：贪嗔痴慢疑的完整映射（205） <a class="header-anchor" href="#三、交易心理-贪嗔痴慢疑的完整映射-205" aria-label="Permalink to &quot;三、交易心理：贪嗔痴慢疑的完整映射（205）&quot;">​</a></h2><p>佛教五毒对照交易行为，逐条展开（205 原文框架）：</p><table tabindex="0"><thead><tr><th>五毒</th><th>交易中的表现</th><th>帖内证据</th><th>对策</th></tr></thead><tbody><tr><td><strong>贪</strong></td><td>进市场原动力即贪婪（否则存银行）；泡沫皆由贪婪起；赚了想赚更多</td><td>77 的&quot;4 倍配资 30 倍利润&quot;诱惑</td><td>贪婪不是坏事，但必须规则化：把&quot;想赚更多&quot;翻译成分级止盈（64 的 5/8/13 日 30/40/30%）与浮盈取半</td></tr><tr><td><strong>嗔</strong></td><td>面对损失与错误时的愤怒；&quot;砍手的冲动，怎么忍不住就卖了&quot;</td><td>205 作者本人后来骂网友&quot;傻逼&quot;、怒而弃帖——嗔的活体展示</td><td>愤怒是离场信号，不是加仓信号；情绪激动当日不做新决策</td></tr><tr><td><strong>痴</strong></td><td>对方法的迷恋：以为技术分析是一切／以为掌握价值投资真谛／以为小道消息能赚钱；作者自省&quot;非要突破 3406&quot;是痴</td><td>205；77 苦练个股技术却三次满仓硬抗</td><td>承认任何指标胜率&lt;100%；回测必须计入交易成本与滑点（205），否则指标只是巧合；找一两个胜率&gt;50% 的指标容易，靠它赚钱的没几个</td></tr><tr><td><strong>慢</strong></td><td>以自我为中心，&quot;以为自己掌握了宇宙真理，手握屠龙宝刀&quot;；市场八亏一平一胜，凭什么赚钱的是你——&quot;人人皆自恋&quot;</td><td>77：&quot;最惨的 530 也才三个跌停，总不可能所有股都六七个跌停吧？&quot;——两波千股跌停随即发生</td><td>用基准率校准自信：默认自己属于 90%；&quot;历史上没发生过&quot;不构成安全边际</td></tr><tr><td><strong>疑</strong></td><td>走势与预期相反时怀疑系统、违反操作原则；买卖点出现时为一两分钱差价犹豫错失</td><td>205</td><td>系统信号触发即执行，与上一单盈亏无关（64：&quot;交易策略由当前趋势状态确定，而不是由这单子之前赚了还是亏了来定&quot;）</td></tr></tbody></table><p><strong>损失厌恶三大通病与对策（205，卡尼曼前景理论）</strong>：</p><ol><li><strong>被套不割肉</strong>：账面亏损还留着&quot;解套希望&quot;，割肉=承认失败、变成实亏 → 对策：把&quot;承认失败的心理成本&quot;与&quot;账户继续失血的资金成本&quot;分开记账，只比较后者；</li><li><strong>牛市拿不住、股票换来换去</strong> → 对策：牛市少动（205：&quot;布林线准确率还行，牛市里股票要少动；少看 KDJ，超买很容易修复&quot;）；</li><li><strong>熊市一套就装死</strong> → 对策：底部区域主动分批买、从高往低买（153），装死是放弃系统。</li></ol><p><strong>为什么坏习惯戒不掉（205）</strong>：斯金纳间歇性强化——回报不固定且不可预测时，行为最会上瘾（老鼠实验：随机掉食物比固定掉食物更让老鼠上瘾）；投机回报&quot;有时沮丧有时狂喜&quot;，正是最强强化剂。<strong>对策只能靠结构：把决策权交给事先写好的规则，而不是交给当时的情绪。</strong></p><p><strong>情绪即信号（205）</strong>：索罗斯&quot;每当他背痛发作，可能就面临危险了&quot;——理智未察觉的危险，身体先知道。情绪不是噪音，是数据。</p><p><strong>风险认知偏差（205）</strong>：人类对极小概率无感性认识——彩票几千万分之一照买，9·11 后美国人改开车，交通事故死亡是恐袭的十几倍。<strong>对小概率利空过度恐慌、对小概率暴利过度追捧，是同一个 bug。</strong></p><hr><h2 id="四、赌场的负期望数学-120-22" tabindex="-1">四、赌场的负期望数学（120 / 22） <a class="header-anchor" href="#四、赌场的负期望数学-120-22" aria-label="Permalink to &quot;四、赌场的负期望数学（120 / 22）&quot;">​</a></h2><h3 id="_4-1-抽水率-×-下注频率-必输-120" tabindex="-1">4.1 抽水率 × 下注频率 = 必输（120） <a class="header-anchor" href="#_4-1-抽水率-×-下注频率-必输-120" aria-label="Permalink to &quot;4.1 抽水率 × 下注频率 = 必输（120）&quot;">​</a></h3><p><strong>费率结构（120 原文数字）</strong>：水子（抽头）按注收 5% 或 10%；码钱（高利贷）利息 10%、<strong>一天一算</strong>；实测&quot;一万元/一天收取 500—600 元水子&quot;，即<strong>日息 5%—6%，月息超 150%</strong>。</p><p><strong>必输推导【由 120 数据推演】</strong>：设单注输赢概率各半（对赌客已是最乐观假设），单注期望 = 0.5×(+1) + 0.5×(-1) − 10%×注码 = <strong>−5%</strong>。一晚下注 50 注，期望损耗 = −250% 本金——这就是为什么赌场不设赌客输光上限、只设时间上限。<strong>实证（120）</strong>：场主阿总拿 2 万元亲自下场&quot;不急不忙慢慢赌&quot;，输赢相抵，&quot;反正他的目的达到了&quot;——一晚光水子就打出四五千（本金的 20%—25%）。他不是在赌，是在给公司制造流水；普通赌客连这个身份都没有。</p><p><strong>对手的三重优势（120）</strong>：① 水子=每注交税；② 资金无限+可输可赢（自己人轮番上场&quot;冲气氛&quot;，注码可输、水子必赚）；③ 出千与暴力。赌客任何&quot;策略&quot;都无法改变&quot;每注都在交税&quot;的事实。</p><p><strong>风险预算的反面教材（120）</strong>：赌场每天从利润提留 3000 元专用于&quot;被抓后平事捞人&quot;——连犯罪组织都懂风险预算，散户账户却没有一分钱是留给极端行情的（对照 77 的 300 万教训）。</p><p><strong>结局链条（120）</strong>：输光→拿码→10% 日息→还不上→卖房卖车→四处编谎借钱→跑路→&quot;被伤身&quot;。作者本人&quot;从有小积蓄到一文不名、负债累累&quot;，身边人妻离子散家破人亡。</p><h3 id="_4-2-出千的层级-武的技与文的局-22" tabindex="-1">4.2 出千的层级：武的技与文的局（22） <a class="header-anchor" href="#_4-2-出千的层级-武的技与文的局-22" aria-label="Permalink to &quot;4.2 出千的层级：武的技与文的局（22）&quot;">​</a></h3><p><strong>分工谱系（22）</strong>：带局（拉赌客）、放贷、收贷、托、前台、后台、红脸、白脸、文、武——技术只是其中一环。</p><p><strong>三档局（22）</strong>：高档千局（对象、环境精心挑选，重布局、技术要求反而低，&quot;相对安全&quot;）；朋友局（相对安全）；散场杂局（风险极大，局中局、黑吃黑频发）。</p><p><strong>核心命题（22）</strong>：**千术杀伤力最大的一块是背后的运作（文），技术（武）只排第二。**理由：技术是死的——&quot;你懂就懂，不懂，它就绝对可以在你眼皮底下使用&quot;；智慧是活的——同样的技术，高端老千能让目标&quot;伤筋动骨乃至倾家荡产&quot;，低端老千&quot;充其量赢完对方手头的钱&quot;。&quot;定江山靠的是文，武只不过是不可或缺的手段。&quot;</p><p><strong>实战识别术（22）</strong>：上场先做两三次出千动作——对方毫无反应，则对方要么是&quot;水鱼&quot;（可拿下），要么在装（等你出千赢大钱后抓你敲诈）；真正的设局者&quot;一般都会先让老千出千赢一大笔，再下手捉千&quot;。防身法：把出千与赌运气的动作做到完全一致、穿插混淆、不形成规律，让对方&quot;知道你在出千，却无法确定哪一手&quot;。</p><p><strong>迁移到市场【推演】</strong>：股市里&quot;武&quot;=技术指标、打板手法，&quot;文&quot;=消息面、资金面、规则面的布局。散户学&quot;武&quot;（K线、龙虎榜），死于&quot;文&quot;（你看到的利好是谁布的局、你追的热点是谁做的气氛）。<strong>判断一场&quot;机会&quot;先问：谁是带局的，谁是托，水子谁抽。</strong></p><hr><h2 id="五、庄家-主力视角-跟庄的危险与对手盘-77-205-191" tabindex="-1">五、庄家/主力视角：跟庄的危险与对手盘（77 / 205 / 191） <a class="header-anchor" href="#五、庄家-主力视角-跟庄的危险与对手盘-77-205-191" aria-label="Permalink to &quot;五、庄家/主力视角：跟庄的危险与对手盘（77 / 205 / 191）&quot;">​</a></h2><p><strong>资金武器层级（77）</strong>：皇族资金（核武器）→ 王族资金（导弹）→ 龙级/虎级游资（坦克飞机大炮）→ 大户牛散（机关枪）→ 散户（赤手空拳）。&quot;哪怕他们自身毫无武功、弱智脑残，但掌握的武器牛逼。&quot;越内层越能分到最大蛋糕并决定外层命运；<strong>在皇族眼里，庄家和游资&quot;也只不过是稍微大一点的屁民、肥嫩点的羊羔&quot;。</strong></p><p><strong>游资生态样本（77）</strong>：2015 年中信溧阳路龙虎榜上榜 680 次/成交 860 亿，银河绍兴（赵老哥，&quot;八年一万倍&quot;，中国神车一役达 10 亿级）上榜 360 亿——他们上的股&quot;无一例外全是大牛股&quot;，同时也是绞肉机：&quot;被他们上完后的股，基本上都报废了，从此一蹶不振。&quot;徐翔式出货=&quot;一字断魂刀&quot;：从涨停直接砸到跌停，散户当天 -20%，&quot;所过之处寸草不生&quot;；而徐翔本人 2015 年谢幕入狱——<strong>庄家游资随时可被查</strong>（77：&quot;想搞你，随时都能拿出铁证来；什么时候处罚，全看老爷们的心情&quot;）。</p><p><strong>主力手法清单（77）</strong>：</p><ul><li>洗盘极端化：反复&quot;砸到快跌停再暴力拉起&quot;——&quot;没有 20% 的巨震，怎么洗得出融资盘&quot;；</li><li>权重压制：证券、银行板块一涨就查两融查合规，&quot;硬砸证券股成了控制大盘上涨过快的有效工具，屡试不爽&quot;——你按基本面重仓券商，可能恰好重仓在别人的刹车上；</li><li>救市逻辑：毫无效果的救市越救越跌（77 观点：量化动量模型做空），国家队现身后 1400 多家上市公司前十大股东可见其身影、市值两万多亿（205）；</li><li>跷跷板节奏（205）：国家队拉银行券商则创业板萎靡，反之亦然——把握节奏者赚，追涨者被两头打。</li></ul><p><strong>跟庄的三条危险（77/191 综合）</strong>：</p><ol><li>你以为在跟庄，庄以为在猎你——你的买点就是他的卖点池；</li><li>庄家本身是猎物——跟庄=把命运绑在另一个随时被查的赌徒身上；</li><li>唯一可持续的&quot;跟庄&quot;是 191 的说法：&quot;做主力肚里的蛔虫&quot;——研究对象是<strong>主力的行为习惯</strong>（手法、成本、出货偏好），不是 K 线形态；前提是你像 77 那样在一只票上花 2500 小时，且即便如此，77 的结论仍是：<strong>大盘系统性风险来临时，个股功夫全部失效</strong>。</li></ol><hr><h2 id="六、币圈知识-208" tabindex="-1">六、币圈知识（208） <a class="header-anchor" href="#六、币圈知识-208" aria-label="Permalink to &quot;六、币圈知识（208）&quot;">​</a></h2><p><strong>货币演化律</strong>：货币史=非货币价值不断递减、货币价值不断提升的历史：粮食→海贝→铜贝→金银（须精深加工提升货币价值）→纸币（非货币价值≈0，&quot;擦屁股都嫌小&quot;）→数字货币（完全脱离有形实体）。每次跳跃都释放巨大经济动能（纸币诞生后经济一日千里）。</p><p><strong>分布式信用（208 核心论点）</strong>：数字货币最大的革命不是无钞流通（省掉押运、网点、ATM、金库、验钞、找零的全部成本），而是<strong>信用的创新</strong>——终结&quot;货币必须由一个超级机构背书&quot;的历史，改为分布式背书：每个小店家、企业、个人以自己的产品和服务直接为其背书。论证锚点是黄金：黄金的信用从来不是某机构强制的，而是&quot;几乎每个人、每个机构不约而同认可&quot;。<strong>比特币=数字黄金/数字硬通货；预判其不取代法币，而是替代黄金的金融职能并促进法币健康运行。</strong></p><p><strong>时间检验的证据（208）</strong>：接受比特币支付的商户（Coinmap.org）从约 1800 家（2013.12）增至 4200 家（2014），其间价格腰斩、中国政府打压——背书数与价格脱钩上行，即分布式信用的形成过程。</p><p><strong>法币侧的数据（208）</strong>：宝鸡刘先生 22 年前存 100 元，活期利息总计不足 8 元——22 年前这是普通技术员一个月工资；90 年代退休工程师一生工资奖金总和约 3—4 万元。<strong>结论：在货币霸权下，长期储蓄是负期望资产；通胀盘剥&quot;现在依旧在你我身上发生着&quot;。</strong></p><p><strong>比特币价值论证（208）</strong>：黄金的致命问题是不能无限向下分割，稀少即瓶颈；比特币可分割至小数点后 100 位，不受稀少制约；即便未来找到其&quot;致命弱点&quot;将其扼杀，&quot;也会有另一个更好的币来替代，世界潮流不可逆&quot;——故越跌越买是&quot;大鳄帮大家降低进场成本&quot;。<strong>此判断的风险面【推演】：它同时意味着任何单一币种都不是终局，重仓单币=承担&quot;更好替代品出现&quot;的尾部风险；帖内老粉丝重仓山寨币跌十几倍回本无望即是实证。</strong></p><p><strong>央行动向预判（208）</strong>：央行打压反而可能&quot;帮助比特币达成统一全球的目的&quot;（应对有问题）；2020 年补判：黄金&quot;回光返照，了解数字货币越多、摒弃黄金的人越多&quot;；央行数字货币影响按其长期判断发展；货币发行权之争（财政部国债 vs 央行垄断）是中国金融核心问题。</p><p><strong>收费贴模式识别（208 自身即样本）</strong>：路径=免费贴养流量→收费贴卖预判→建群维护→&quot;五年内财富自由&quot;承诺→熊市话术锁定（&quot;下跌是刻意压弹簧，压得越凶跳得越高&quot;&quot;现在的涨跌跟你们没关系，有关系的是五年后的价格&quot;&quot;机会多的是，来日方长&quot;）。<strong>识别特征：① 只报方向、不报可验证的仓位与成本；② 亏损归因于&quot;人为操纵&quot;&quot;有人盯着我们&quot;而非自身判断；③ 用超长期主义把一切短期证伪无限延期；④ 以&quot;为你好&quot;的话术劝阻止损。</strong> 免费贴讲知识、收费贴卖方向——方向恰恰是最不值钱的部分。</p><hr><h2 id="七、创业与做生意-139-182" tabindex="-1">七、创业与做生意（139 / 182） <a class="header-anchor" href="#七、创业与做生意-139-182" aria-label="Permalink to &quot;七、创业与做生意（139 / 182）&quot;">​</a></h2><h3 id="_7-1-把一件事做透的三步法-139" tabindex="-1">7.1 把一件事做透的三步法（139） <a class="header-anchor" href="#_7-1-把一件事做透的三步法-139" aria-label="Permalink to &quot;7.1 把一件事做透的三步法（139）&quot;">​</a></h3><p><strong>第一步：目标细分法（把总目标切成可验证小目标）</strong>。范本：英国短跑选手破 200 米纪录——把原世界纪录拆成 0—50 米 6 秒、0—100 米 11 秒、0—150 米、0—200 米四段，逐段苦练、逐段打破。作者 15 天突击室内设计即用此法：目标一&quot;先看懂设计&quot;；目标二&quot;明确主攻方向&quot;——业主最关心客厅、卧室，15 天只学客厅卧室的吊顶与墙壁（先解决主要矛盾，其余不看）；目标三&quot;请教高手&quot;——请设计主任逐图讲解、听不懂再讲、回来自我复讲两遍、做笔记归纳，学完几百张图后&quot;大同小异的设计思路出现了&quot;；目标四&quot;现场实践&quot;——跟随高手走访两三套房，思路↔效果图↔实景互相对应。</p><p><strong>第二步：重复到背诵</strong>。&quot;一张经典设计稿看一年，至少看 100 遍，直到彻底背诵、理解、运用&quot;；一周内背下 5000 张国际包装设计图（用目标细分法切成每日定量）——&quot;笨办法往往是最好的办法&quot;。</p><p><strong>第三步：以客户价值开路，再谈生意</strong>。开篇就谈生意十之八九谈崩；先免费提供价值（发现红牛广告&quot;跑步顺拐&quot;错误→电话指正→获准上门→签 60 万大单）；攻心为上：每周五逐个打传呼祝周末愉快、信封手写一句话、随身小本记录客户衣着与话题下次见面就夸；谈判读肢体语言（对方摸鼻子=已同意、只在讨价还价）；施压三件套：诉苦表演（透露预算紧巴）+ 威胁拆单（把 300 万合同拆成两份让对方多跑两趟领导）+ 以物易物（用 60 万户外广告位置换折扣，&quot;空着也是空着&quot;）。</p><p><strong>风险教育的代价（139）</strong>：作者本人&quot;在对赌期货上栽了大跟头&quot;（非本专业领域）；身边案例——湛江糖王白糖期货对赌亏几个亿，被持械债主逼门，跳楼轻生，<strong>第二天白糖大涨</strong>。&quot;今天是亿万富翁，明天就有可能是乞丐。&quot;跨界投机是能力圈外的高危行为。</p><h3 id="_7-2-润土三次创业失败的政策教训-182" tabindex="-1">7.2 润土三次创业失败的政策教训（182） <a class="header-anchor" href="#_7-2-润土三次创业失败的政策教训-182" aria-label="Permalink to &quot;7.2 润土三次创业失败的政策教训（182）&quot;">​</a></h3><ul><li><strong>第一次（1987，服装）</strong>：产品判断完全正确——分析出进口西装缺陷（日式贴身不便做事、英式开叉被讥&quot;冒充华侨&quot;），设计双排扣不开叉全毛西服，五星级商场单日销量第一，4 个月 1 万变 10 万。死因：合作被定性&quot;投机倒把&quot;；英文商标不许注册；自开厂需 50 万注册资金+20 台设备+380 伏工业电（仅增容就要 8 万现金）。<strong>死于制度，不死于市场。</strong></li><li><strong>第二次（1992，石油）</strong>：发现油票&quot;按吨买、按升卖&quot;的单位换算套利（1 吨汽油=1378 升），免费送油上门绑定中小企业，1 年半 5 万变 100 万。死因：国家石油垄断政策调整。<strong>死于政策转向。</strong></li><li><strong>第三次（传媒）</strong>：10 万投入公交 IC 卡广告整合，做出 450 万利润。死因：合作方毁约，&quot;法律和公正像废纸一样&quot;。<strong>死于契约环境。</strong></li></ul><p><strong>方法论遗产（182）</strong>：创业三要素=经验、资金、关系；&quot;经验可以积累，不过付出一生幸福获得的经验不叫经验，是悔恨&quot;；每次进入新市场前先做&quot;分析市场格局、找出竞争对手破绽&quot;的两件事；&quot;发财与事业是两个概念——发财满足私欲，事业成就辉煌&quot;，用发财心理做事的人永远理解不了张瑞敏、王石。<strong>合成的规则：先问这生意的生存空间由哪条政策/规则授予，政策收回时你死不死；再谈产品与执行。</strong></p><hr><h2 id="八、风控总清单-幸存者共性检查表" tabindex="-1">八、风控总清单：幸存者共性检查表 <a class="header-anchor" href="#八、风控总清单-幸存者共性检查表" aria-label="Permalink to &quot;八、风控总清单：幸存者共性检查表&quot;">​</a></h2><p>以下每条都能在帖内找到正反案例。使用方式：开仓前逐条打勾，有一条不满足即降仓或放弃。</p><ol><li><strong>□ 单笔风险有上限</strong>：单笔潜在亏损×预期连续止损次数 ≤ 总资金 30%【推演】；大机会也只投 10%（64）；极有把握才动用全部仓位做 T 且底仓不动（153）。</li><li><strong>□ 机动现金独立存在</strong>：补保证金/补仓用资金 ≥ 本金 15%，且平时永不挪用（77：差 300 万机动资金，2100 万变 70 万）。</li><li><strong>□ 杠杆乘以历史极值后仍活着</strong>：杠杆倍数 ×（历史极端连续跌幅，A 股按两日 -16% 以上）&lt; 100%，最好 &lt; 70%（77：6 倍杠杆跌 13% 即触强平线；&quot;所有股六七个跌停&quot;在 2015 年真实发生）。</li><li><strong>□ 知道自己的股票今天能不能卖</strong>：T+1 当日买入无法卖出=强平保护失效（77 猛人案例）；节假日前、重大会议/数据前主动降杠杆（64：08 年国庆金属单月 -40%；77：十八大&quot;开会必跌魔咒&quot;反用）。</li><li><strong>□ 浮盈不自动变仓位</strong>：浮盈加仓只在大趋势初段（64 状态×级别规则），趋势末端浮盈取半落袋（64）；绝不&quot;赚了 500 万就加 500 万仓&quot;（77）。</li><li><strong>□ 止损是成本不是失败</strong>：-3%~-6% 坚决执行（191 实盘单）；行情降级时预期同步降级（191：&quot;从想赚钱改为亏 5% 以内出局&quot;）。</li><li><strong>□ 系统不覆盖的极端有预案</strong>：停牌、无征兆连板跌停、千股跌停=系统外事件，只能靠仓位冗余兜底（153、64、77 三帖共同结论）。</li><li><strong>□ 明白对手是谁</strong>：跟的是热点还是别人的出货池；主力行为习惯研究透了再谈&quot;跟庄&quot;（191、77）；记住资金武器层级——散户唯一的武器是仓位与时间（77）。</li><li><strong>□ 情绪自检</strong>：嗔（愤怒）发作当日不做新决策；背痛/失眠等身体信号视为风险信号（205/索罗斯）；连续两笔情绪单后强制空仓一日。</li><li><strong>□ 概率敏感化</strong>：任何指标先问回测是否含交易成本与滑点（205）；对极小概率的暴利（彩票式打板）与灾难（连板跌停）都按&quot;会发生在自己身上&quot;定价（205 的 9·11 案例反证）。</li><li><strong>□ 有记录有复盘</strong>：贴结算单、写收评、记客户小本（153/191/139）——不能复盘的利润是不可复制的运气。</li><li><strong>□ 知道退出条件</strong>：赌桌的退出=离开赌场（120/22 作者们用半生验证&quot;十赌十诈&quot;后戒赌）；市场的退出=当&quot;政策收回生存空间&quot;时离场（182 三次创业、77 弃股从文）。<strong>幸存者的最后一项共性：都活到了把经验写成文字的那一天。</strong></li></ol><hr><h3 id="附-本手册十帖速查" tabindex="-1">附：本手册十帖速查 <a class="header-anchor" href="#附-本手册十帖速查" aria-label="Permalink to &quot;附：本手册十帖速查&quot;">​</a></h3><table tabindex="0"><thead><tr><th>帖号</th><th>作者</th><th>年代</th><th>提供的核心知识</th></tr></thead><tbody><tr><td>77</td><td>南侠1987</td><td>2015—2016</td><td>配资爆仓数学、浮盈加仓陷阱、应急资金、资金层级</td></tr><tr><td>153</td><td>数字哥</td><td>2011—2019</td><td>缠论前10章、分钟背离共振、高抛低吸、做T</td></tr><tr><td>191</td><td>岑若曦</td><td>2015—2020</td><td>涨停股模式、热点聚焦、止损纪律、复利观</td></tr><tr><td>64</td><td>peterwind</td><td>2015—2018</td><td>大突破策略、多周期共振、轻仓铁律、状态定仓</td></tr><tr><td>205</td><td>时代之</td><td>2015—2016</td><td>前景理论、损失厌恶、贪嗔痴慢疑、间歇性强化</td></tr><tr><td>120</td><td>背上痒难受</td><td>2008—2009</td><td>抽水率、码钱利率、赌场成本结构、风险预算</td></tr><tr><td>22</td><td>揭育润</td><td>2011—2018</td><td>千术层级（武/文）、局的分档、水鱼识别</td></tr><tr><td>208</td><td>冻云迷雾</td><td>2014—2020</td><td>货币演化律、分布式信用、法币通胀数据、收费贴模式</td></tr><tr><td>139</td><td>万里依然</td><td>2010—2014</td><td>目标细分法、做透三步、攻心谈判、期货教训</td></tr><tr><td>182</td><td>润土</td><td>2005—2019</td><td>三次创业、政策教训、发财与事业之辨</td></tr></tbody></table>',98)])])}const h=o(q,[["render",s]]);export{p as __pageData,h as default};
